             new P.Campo("Seletor.Selecionado", "Paciente", "selecao", "Seletor.Resultados", "Nome"),
             new P.Campo("Paciente", "Pagamentos na recepção", "leitura", Visivel: "TemPaciente"),
             new P.Campo("Resumo", "Pagamentos na recepção", "leitura", Visivel: "TemPaciente")], [],
            [
                new P.Secao("Linhas", "Linhas", null, [], [],
                    [PT("Linhas", [new P.Coluna("Descricao", "Sessão / cobrança"), new P.Coluna("Vencimento", "Vencimento"), new P.Coluna("Valor", "Valor"), new P.Coluna("Situacao", "Situação")], [], [new P.Acao("Receber", "Receber", Guarda: null, SemParametro: false, Visivel: "EmAberto", Parametro: null), new P.Acao("Recibo", "Recibo", Guarda: null, SemParametro: false, Visivel: "Recebido", Parametro: null)], "TemPaciente")], []),
            ],
            [new P.Acao("Seletor.DesligarSugestao", "Ver todos"),
             new P.Acao("TrocarPaciente", "Trocar paciente", Guarda: null, SemParametro: false, Visivel: "TemPaciente", Parametro: null),
             new P.Acao("Carregar", "Atualizar", Guarda: null, SemParametro: false, Visivel: "TemPaciente", Parametro: null)], Permissao: Permissao.VenderPacote, Fabrica: sp => PrepararPagina(sp, sp.GetRequiredService<PagamentosViewModel>(), "pagamentos-recepcao"), AoAbrir: AbrirPaginaAsync, AoFechar: FecharPagina);
        // Contrato de ConfirmacoesView.xaml; campos e comandos são constantes de apresentação.
        yield return new("agenda-confirmacoes", "Confirmações de agenda", typeof(ConfirmacoesViewModel),
            [new P.Campo("Dia", "Dia", "data", Opcoes: null, RotuloOpcao: null, ValorOpcao: null, Guarda: null, Visivel: null),
             new P.Campo("Resumo", "Confirmar sessões", "leitura", Visivel: null)], [],
