             new P.Acao("EnviarEmails", "Enviar e-mails", Guarda: "PodeEditar", SemParametro: false, Visivel: null, Parametro: null),
             new P.Acao("Carregar", "Atualizar", Guarda: null, SemParametro: false, Visivel: null, Parametro: null)], Permissao: Permissao.VerAgenda, Fabrica: sp => PrepararPagina(sp, sp.GetRequiredService<ConfirmacoesViewModel>(), "agenda-confirmacoes"), AoAbrir: AbrirPaginaAsync, AoFechar: FecharPagina);
    }
    private static P.Tab PT(string origem, P.Coluna[] colunas, P.Campo[] campos, P.Acao[] acoes, string? visivel = null) =>
        new(origem, origem, [origem], vm => ColecaoWeb(vm, origem), colunas, campos, acoes, Visivel: visivel);
    private static IEnumerable<object> ColecaoWeb(object vm, string caminho)
    {
        object? valor = vm; foreach (var parte in caminho.Split('.')) valor = valor?.GetType().GetProperty(parte)?.GetValue(valor);
        return (valor as IEnumerable)?.Cast<object>() ?? [];
    }
